const VulkanNativeCommandInfo* GetVulkanNativeCommandInfo(const char* name)
{
    if (name == nullptr)
    {
        return nullptr;
    }
    for (const auto& command : kVulkanNativeCommands)
    {
        if (std::strcmp(command.name, name) == 0)
        {
            return &command;
        }
    }
    return nullptr;
}

